module Tests.Target where

open import Agda.Builtin.Nat
open import Agda.Builtin.Equality

open import Tests.Util
open import Tests.Helpers
open import Tests.Context

addComm : (n m : Nat) → n + m ≡ m + n
-- [lemma/hard] First we establish that for any natural number n, adding zero on the right yields n itself.
addZeroRight zero = {!!}
addZeroRight (suc n) = {!!}

-- [lemma/hard] Next we establish that adding a successor to the left distributes over addition: suc m + n = suc (m + n).
addSucLeft zero n = {!!}
addSucLeft (suc m) n with addSucLeft m n | sym ?_ ...
... | _ , refl ... = {!!}

-- [induction] We now prove commutativity by arguing by induction on n, holding m fixed throughout the argument.
-- Base case: when n is zero, n + m reduces to 0 + m, which equals m by addZeroRight. On the other side, m + 0 reduces directly to m using addZeroRight again. Thus both sides are equal.
addComm zero m = {!!}

-- [case] Inductive case: assume n + m = m + n holds for an arbitrary natural number k (this is our induction hypothesis). We must show that suc n + m equals m + suc n. The left side, suc n + m, reduces to suc (n + m) by addSucLeft. By applying the induction hypothesis to this result and then using symmetry on both sides of the equality we conclude that it equals m + suc n.
addComm (suc n) m with addZeroRight ?_ | trans ?_ ... = {!!}
... | _ , refl ... = {!!}

